package repos

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"

	"opencode-dots/internal/atomicfile"
)

// The generated files, which the other tools keep reading unchanged.
const (
	FileAwfGh    = "awf-gh.yaml"
	FileTend     = "tend.list"
	FileCheckout = "repos.map"
	SourceFile   = "repos.yaml"

	defaultAwfURL    = "http://127.0.0.1:2511"
	defaultStatePath = "/state/awf-gh/seen.jsonl"
	defaultMaxPerRun = 3
)

const header = "Generated by bin/repos from repos.yaml. Do not edit this file: change repos.yaml,\n" +
	"then run `make repos` (the dashboard does it when it saves repos.yaml).\n"

// EffectiveSettings fills what repos.yaml leaves empty: first the value the
// previous generated awf-gh.yaml carried (bin/configure writes the awf_url and
// state_path that fit local or docker mode), then the built-in default.
func EffectiveSettings(doc, previous, override Settings) Settings {
	pick := func(vals ...string) string {
		for _, v := range vals {
			if v != "" {
				return v
			}
		}
		return ""
	}
	out := Settings{
		AwfURL:    pick(override.AwfURL, doc.AwfURL, previous.AwfURL, defaultAwfURL),
		StatePath: pick(override.StatePath, doc.StatePath, previous.StatePath, defaultStatePath),
		MaxPerRun: defaultMaxPerRun,
		Executors: doc.Executors,
		DotID:     doc.DotID,
	}
	for _, n := range []int{override.MaxPerRun, doc.MaxPerRun, previous.MaxPerRun} {
		if n > 0 {
			out.MaxPerRun = n
			break
		}
	}
	return out
}

// ExecutorFile is the watcher file of one named executor.
func ExecutorFile(name string) string { return "awf-gh." + name + ".yaml" }

// IsWatcherFile reports whether a file name is one the generator writes for the
// watcher: awf-gh.yaml, or awf-gh.<executor>.yaml with a plain executor name.
func IsWatcherFile(name string) bool {
	if name == FileAwfGh {
		return true
	}
	mid, ok := strings.CutSuffix(strings.TrimPrefix(name, "awf-gh."), ".yaml")
	return strings.HasPrefix(name, "awf-gh.") && ok && executorName.MatchString(mid)
}

// forExecutor gives the settings of the watcher file of one executor: its own
// awf_url, and a state file next to the default one so the seen markers of two
// watchers never mix.
func (s Settings) forExecutor(name string) Settings {
	ext := path.Ext(s.StatePath)
	s.AwfURL = s.Executors[name]
	s.StatePath = strings.TrimSuffix(s.StatePath, ext) + "-" + name + ext
	return s
}

// ReadSettings reads the three watcher settings back from a generated (or older
// hand written) awf-gh.yaml. A missing file gives empty settings; a file that
// cannot be read or does not parse is an error, so its values are not replaced
// by defaults.
func ReadSettings(path string) (Settings, error) {
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return Settings{}, nil
	}
	if err != nil {
		return Settings{}, fmt.Errorf("%s: %w", filepath.Base(path), err)
	}
	var s Settings
	if err := yaml.Unmarshal(data, &s); err != nil {
		return Settings{}, fmt.Errorf("%s: %w", filepath.Base(path), err)
	}
	return s, nil
}

// Render produces the content of every generated file. A watcher file exists
// only when a repository enables a watch rule: the watcher is opt-in, and a
// server that only tends does not use it. awf-gh takes one awf_url per file, so
// the rules of each executor go to a file of their own (ADR 0031).
func Render(out *Output, s Settings) (map[string][]byte, error) {
	files := map[string][]byte{}
	groups := map[string][]Rule{}
	for _, rule := range out.Rules {
		groups[rule.Executor] = append(groups[rule.Executor], rule)
	}
	executors := make([]string, 0, len(groups))
	for name := range groups {
		executors = append(executors, name)
	}
	slices.Sort(executors)
	for _, name := range executors {
		file, settings := FileAwfGh, s
		if name != "" {
			file, settings = ExecutorFile(name), s.forExecutor(name)
		}
		body, err := renderAwfGh(groups[name], settings)
		if err != nil {
			return nil, err
		}
		files[file] = withSkipped(body, out.Skipped)
	}
	files[FileTend] = withSkipped(renderLines(out.Tend, tendLine), out.Skipped)
	files[FileCheckout] = withSkipped(renderLines(out.Checkout, func(c CheckoutEntry) string { return c.Repo + "=" + c.Path }), out.Skipped)
	for name, lines := range out.Files {
		if name != filepath.Base(name) || strings.HasPrefix(name, ".") {
			return nil, fmt.Errorf("feature file %q must be a plain file name", name)
		}
		if _, taken := files[name]; taken || name == SourceFile {
			return nil, fmt.Errorf("feature file %q collides with another generated file", name)
		}
		files[name] = withSkipped([]byte(commentHeader()+strings.Join(lines, "\n")+"\n"), out.Skipped)
	}
	return files, nil
}

func commentHeader() string {
	var b strings.Builder
	for line := range strings.SplitSeq(strings.TrimRight(header, "\n"), "\n") {
		b.WriteString("# " + line + "\n")
	}
	return b.String()
}

func renderLines[T any](items []T, line func(T) string) []byte {
	var b strings.Builder
	b.WriteString(commentHeader())
	for _, item := range items {
		b.WriteString(line(item) + "\n")
	}
	return []byte(b.String())
}

func renderAwfGh(rules []Rule, s Settings) ([]byte, error) {
	root := &yaml.Node{Kind: yaml.MappingNode}
	add := func(m *yaml.Node, key string, value *yaml.Node) {
		m.Content = append(m.Content, &yaml.Node{Kind: yaml.ScalarNode, Value: key}, value)
	}
	str := func(v string) *yaml.Node { return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: v} }
	flow := func(values []string) *yaml.Node {
		n := &yaml.Node{Kind: yaml.SequenceNode, Style: yaml.FlowStyle}
		for _, v := range values {
			n.Content = append(n.Content, str(v))
		}
		return n
	}
	add(root, "awf_url", str(s.AwfURL))
	add(root, "state_path", str(s.StatePath))
	add(root, "max_per_run", &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.Itoa(s.MaxPerRun)})
	list := &yaml.Node{Kind: yaml.SequenceNode}
	for _, r := range rules {
		m := &yaml.Node{Kind: yaml.MappingNode}
		add(m, "repo", str(r.Repo))
		if r.Scope != "" {
			add(m, "scope", str(r.Scope))
		}
		add(m, "workflow", str(r.Workflow))
		add(m, "on", flow(r.On))
		if len(r.IgnoreAuthors) > 0 {
			add(m, "ignore_authors", flow(r.IgnoreAuthors))
		}
		if len(r.OnlyAuthors) > 0 {
			add(m, "only_authors", flow(r.OnlyAuthors))
		}
		if len(r.Labels) > 0 {
			add(m, "labels", flow(r.Labels))
		}
		if len(r.Inputs) > 0 {
			in := &yaml.Node{Kind: yaml.MappingNode}
			keys := make([]string, 0, len(r.Inputs))
			for k := range r.Inputs {
				keys = append(keys, k)
			}
			slices.Sort(keys)
			for _, k := range keys {
				add(in, k, str(r.Inputs[k]))
			}
			add(m, "inputs", in)
		}
		list.Content = append(list.Content, m)
	}
	add(root, "repos", list)
	var buf bytes.Buffer
	buf.WriteString(commentHeader())
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(root); err != nil {
		return nil, err
	}
	if err := enc.Close(); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// Diff lists the generated files whose content differs from what is in dir.
func Diff(dir string, files map[string][]byte) []string {
	var changed []string
	for name, want := range files {
		got, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil || !bytes.Equal(got, want) {
			changed = append(changed, name)
		}
	}
	slices.Sort(changed)
	return changed
}

// Write stores the files that changed, each through a temporary file and a
// rename so a reader never sees half of one, and returns the names it wrote,
// which on an error are only the ones written before it.
func Write(dir string, files map[string][]byte) ([]string, error) {
	var written []string
	for _, name := range Diff(dir, files) {
		if info, err := os.Lstat(filepath.Join(dir, name)); err == nil && !info.Mode().IsRegular() {
			return written, fmt.Errorf("write %s: not a regular file", name)
		}
		if err := atomicfile.Write(filepath.Join(dir, name), files[name], 0o644); err != nil {
			return written, fmt.Errorf("write %s: %w", name, err)
		}
		written = append(written, name)
	}
	return written, nil
}

// Build is the whole pipeline from repos.yaml bytes to generated files: parse,
// resolve, run the features, fill the settings and render. The caller decides
// whether to write.
func Build(data []byte, dir string, override Settings) (map[string][]byte, error) {
	doc, err := Parse(data)
	if err != nil {
		return nil, err
	}
	return BuildDocument(doc, dir, override)
}

// BuildDocument is Build for a document that is already parsed, such as one made from the
// database (ADR 0024).
func BuildDocument(doc *Document, dir string, override Settings) (map[string][]byte, error) {
	if err := checkExecutors(doc.Settings); err != nil {
		return nil, err
	}
	if err := checkTrust(doc.Settings); err != nil {
		return nil, err
	}
	if err := checkHints(doc.Settings); err != nil {
		return nil, err
	}
	if err := checkDot(doc.Settings); err != nil {
		return nil, err
	}
	out, err := Generate(doc)
	if err != nil {
		return nil, err
	}
	// No watch rule means the watcher is not used: Render leaves awf-gh.yaml out
	// instead of writing a list that awf-gh would refuse.
	previous, err := ReadSettings(filepath.Join(dir, FileAwfGh))
	if err != nil {
		return nil, err
	}
	settings := EffectiveSettings(doc.Settings, previous, override)
	return Render(out, settings)
}
